mapper.update:
UPDATE deals
SET krw_sale_price = #{krwSale}, krw_normal_price = #{krwNormal}
WHERE deal_id = #{dealId}

mapper.select:
SELECT MIN(p) FROM (
    SELECT MIN(sale_price) AS p FROM price_history WHERE game_id = #{gameId}
    UNION ALL
    SELECT MIN(sale_price) FROM deals WHERE game_id = #{gameId}
) t
